use std::collections::HashMap;
use std::net::IpAddr;
use std::sync::Arc;
use std::time::Duration;
use tokio::sync::RwLock;
use hyper::{Body, Response, StatusCode};
use serde::{Deserialize, Serialize};
use hmac::{Hmac, Mac};
use sha2::Sha256;
use url::{Host, Url};

type HmacSha256 = Hmac<Sha256>;

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct ServiceRegistry {
    pub endpoints: HashMap<String, String>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct PaymentRequest {
    pub merchant_id: String,
    pub amount: u64,
    pub currency: String,
    pub callback_url: String,
    pub metadata: HashMap<String, String>,
}

#[derive(Clone)]
pub struct PaymentGateway {
    registry: Arc<RwLock<ServiceRegistry>>,
    signing_key: Vec<u8>,
    allowed_callback_schemes: Vec<String>,
    http_client: reqwest::Client,
}

impl PaymentGateway {
    pub fn new(signing_key: Vec<u8>) -> Self {
        let mut endpoints = HashMap::new();
        endpoints.insert("ledger".to_string(), "http://internal-ledger:8080".to_string());
        endpoints.insert("fraud".to_string(), "http://internal-fraud:8081".to_string());
        endpoints.insert("notification".to_string(), "http://internal-notify:8082".to_string());

        // Reuse a single client with a bounded timeout to avoid socket
        // exhaustion and hanging upstream calls.
        let http_client = reqwest::Client::builder()
            .timeout(Duration::from_secs(10))
            .build()
            .expect("failed to build reqwest client");

        Self {
            registry: Arc::new(RwLock::new(ServiceRegistry { endpoints })),
            signing_key,
            allowed_callback_schemes: vec!["https".to_string()],
            http_client,
        }
    }

    fn generate_auth_token(&self, service_name: &str, request_id: &str) -> Result<String, String> {
        let mut mac = HmacSha256::new_from_slice(&self.signing_key)
            .map_err(|e| format!("HMAC key error: {}", e))?;
        mac.update(format!("{}:{}", service_name, request_id).as_bytes());
        Ok(hex::encode(mac.finalize().into_bytes()))
    }

    /// Returns true if the IP address belongs to a range that must never be
    /// reachable from a public callback (loopback, private, link-local,
    /// unspecified, or unique-local IPv6).
    fn is_disallowed_ip(ip: &IpAddr) -> bool {
        match ip {
            IpAddr::V4(v4) => {
                v4.is_loopback()
                    || v4.is_private()
                    || v4.is_link_local()
                    || v4.is_unspecified()
                    || v4.is_broadcast()
                    || v4.is_documentation()
                    // 169.254.169.254 (cloud metadata) is covered by link_local.
            }
            IpAddr::V6(v6) => {
                v6.is_loopback()
                    || v6.is_unspecified()
                    // Unique local addresses fc00::/7
                    || (v6.segments()[0] & 0xfe00) == 0xfc00
                    // Link-local fe80::/10
                    || (v6.segments()[0] & 0xffc0) == 0xfe80
                    // IPv4-mapped: re-check the embedded IPv4 address.
                    || v6.to_ipv4().map(|m| Self::is_disallowed_ip(&IpAddr::V4(m))).unwrap_or(false)
            }
        }
    }

    fn validate_callback_url(&self, url_str: &str) -> Result<Url, String> {
        let parsed = Url::parse(url_str)
            .map_err(|e| format!("Invalid URL: {}", e))?;

        if !self.allowed_callback_schemes.contains(&parsed.scheme().to_string()) {
            return Err("Only HTTPS callbacks allowed".to_string());
        }

        let host = parsed.host()
            .ok_or("Missing host")?;

        match host {
            Host::Ipv4(ip) => {
                if Self::is_disallowed_ip(&IpAddr::V4(ip)) {
                    return Err("Disallowed IP address".to_string());
                }
            }
            Host::Ipv6(ip) => {
                if Self::is_disallowed_ip(&IpAddr::V6(ip)) {
                    return Err("Disallowed IP address".to_string());
                }
            }
            Host::Domain(domain) => {
                let lower = domain.to_ascii_lowercase();
                // Reject obvious loopback/metadata hostnames. Note: DNS
                // rebinding is best mitigated at request time by the
                // notification service; here we block the common cases.
                if lower == "localhost"
                    || lower.ends_with(".localhost")
                    || lower == "metadata"
                    || lower == "metadata.google.internal"
                {
                    return Err("Disallowed host".to_string());
                }
                // If the domain literally parses to an IP, validate it too.
                if let Ok(ip) = lower.parse::<IpAddr>() {
                    if Self::is_disallowed_ip(&ip) {
                        return Err("Disallowed IP address".to_string());
                    }
                }
            }
        }

        Ok(parsed)
    }

    async fn resolve_service_endpoint(&self, service_name: &str) -> Option<String> {
        let registry = self.registry.read().await;
        registry.endpoints.get(service_name).cloned()
    }

    async fn dispatch_to_service(
        &self,
        service_name: &str,
        path: &str,
        payload: &[u8],
        request_id: &str,
    ) -> Result<Vec<u8>, String> {
        let base_url = self.resolve_service_endpoint(service_name).await
            .ok_or(format!("Service '{}' not found", service_name))?;

        let token = self.generate_auth_token(service_name, request_id)?;
        let full_url = format!("{}{}", base_url, path);

        let resp = self.http_client.post(&full_url)
            .header("X-Internal-Auth", token)
            .header("X-Request-Id", request_id)
            .body(payload.to_vec())
            .send()
            .await
            .map_err(|e| format!("Service call failed: {}", e))?;

        resp.bytes().await
            .map(|b| b.to_vec())
            .map_err(|e| format!("Read response failed: {}", e))
    }

    pub async fn process_payment(&self, req: PaymentRequest) -> Result<Response<Body>, String> {
        let request_id = uuid::Uuid::new_v4().to_string();

        // Step 1: Validate callback URL
        let _validated_cb = self.validate_callback_url(&req.callback_url)?;

        // Step 2: Fraud check
        let fraud_payload = serde_json::to_vec(&serde_json::json!({
            "merchant_id": req.merchant_id,
            "amount": req.amount,
            "currency": req.currency,
        })).map_err(|e| format!("Serialization error: {}", e))?;

        let fraud_result = self.dispatch_to_service(
            "fraud", "/api/v1/check", &fraud_payload, &request_id
        ).await?;

        let fraud_response: serde_json::Value = serde_json::from_slice(&fraud_result)
            .map_err(|e| format!("Invalid fraud response: {}", e))?;

        if fraud_response["risk_score"].as_u64().unwrap_or(100) > 80 {
            return Err("Payment rejected: high risk".to_string());
        }

        // Step 3: Record in ledger
        let ledger_payload = serde_json::to_vec(&serde_json::json!({
            "merchant_id": req.merchant_id,
            "amount": req.amount,
            "currency": req.currency,
            "request_id": request_id,
        })).map_err(|e| format!("Serialization error: {}", e))?;

        self.dispatch_to_service(
            "ledger", "/api/v1/record", &ledger_payload, &request_id
        ).await?;

        // Step 4: Send notification via webhook
        // The notification service will call the merchant's callback
        let notify_payload = self.build_notification_payload(&req, &request_id)?;

        self.dispatch_to_service(
            "notification", "/api/v1/webhook", &notify_payload, &request_id
        ).await?;

        Response::builder()
            .status(StatusCode::OK)
            .body(Body::from(format!("{{\"request_id\": \"{}\"}}", request_id)))
            .map_err(|e| format!("Response build error: {}", e))
    }

    fn build_notification_payload(&self, req: &PaymentRequest, request_id: &str) -> Result<Vec<u8>, String> {
        // Always use the validated callback_url for webhook delivery.
        // The metadata field is for informational purposes only and never
        // used to override delivery targets.
        let target_url = &req.callback_url;

        serde_json::to_vec(&serde_json::json!({
            "target_url": target_url,
            "request_id": request_id,
            "merchant_id": req.merchant_id,
            "event": "payment.completed",
            "amount": req.amount,
        })).map_err(|e| format!("Serialization error: {}", e))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_callback_validation_blocks_localhost() {
        let gw = PaymentGateway::new(b"test-key".to_vec());
        assert!(gw.validate_callback_url("https://localhost/hook").is_err());
        assert!(gw.validate_callback_url("https://127.0.0.1/hook").is_err());
        assert!(gw.validate_callback_url("http://example.com/hook").is_err());
    }

    #[test]
    fn test_callback_validation_blocks_private_ranges() {
        let gw = PaymentGateway::new(b"test-key".to_vec());
        assert!(gw.validate_callback_url("https://10.0.0.1/hook").is_err());
        assert!(gw.validate_callback_url("https://192.168.1.1/hook").is_err());
        assert!(gw.validate_callback_url("https://169.254.169.254/hook").is_err());
        assert!(gw.validate_callback_url("https://0.0.0.0/hook").is_err());
    }

    #[test]
    fn test_callback_validation_allows_https() {
        let gw = PaymentGateway::new(b"test-key".to_vec());
        assert!(gw.validate_callback_url("https://merchant.example.com/hook").is_ok());
    }

    #[test]
    fn test_auth_token_generation() {
        let gw = PaymentGateway::new(b"secret-key".to_vec());
        let token1 = gw.generate_auth_token("ledger", "req-123").unwrap();
        let token2 = gw.generate_auth_token("ledger", "req-123").unwrap();
        assert_eq!(token1, token2);
        let token3 = gw.generate_auth_token("fraud", "req-123").unwrap();
        assert_ne!(token1, token3);
    }
}
